def main():
    completion=json.loads((ROOT/'research/skull-completion-status.json').read_text(encoding='utf-8'))
    expected={int(p['code'].split('.')[-1]) for p in completion['remaining_primary_markers']['temporal_right'] if p['localization']=='projection'}
    assert set(OUTCOMES)==expected and len(expected)==43
    native=json.loads((ROOT/'pins_head/temporal-native-features.json').read_text(encoding='utf-8'))
    markers={m['c']:m for m in native['markers']}
    rows=[]
    for num,(status,finding,next_step) in sorted(OUTCOMES.items()):
        code=f'A02.1.06.{num:03}';lat,ru,_=ta98.T[code]
        row={'code':code,'ru':ru,'lat':lat,'bodyparts3d_records':2,'main_localization_unchanged':'projection',
             'outcome':status,'finding':finding,'remaining_work':next_step,
             'full_feature_geometry_confirmed':False,
             'review_scope':'targeted-native-geometry-review' if code in markers else 'source-capability-and-region-review',
             'anatomical_refs':[{**r,'locator':r.get('locator',r['title']+'; '+lat)} for r in DESCRIPTIONS[code]['refs'][:2]]}
        if code in markers:
            m=markers[code];row.update(native_marker=m['id'],geometry_scope=m['geometryScope'],geometry_evidence=m['evidence'])
        rows.append(row)
    result={'date':'2026-10-13','source':'OpenEar ZETA','geometry_sha256':native['geometry_sha256'],
            'unique_projection_codes':43,'paired_primary_records':86,'new_native_feature_markers':len(markers),
            'complete_temporal_geometry_claim':False,
            'scope':'Аудит каждого из 43 кодов различает целевую проверку геометрии и предварительную проверку возможностей источника. Нерешённая позиция не означает анатомического отсутствия или невозможности получить подходящий исходник.',
            'sampling':{'full_cbct_acquisition_mm':.25,'bone_mask_grid_mm':.125,'embedded_cbct_acquisition_mm':.125,
                        'source':'https://pmc.ncbi.nlm.nih.gov/articles/PMC6326113/','locator':'Methods — Specimen Preparation; Table 1'},
            'orientation':'Собственные координаты образца и векторы камеры; оси RAS не приравнены к анатомической позе.',
            'normal_correction_report':'build_head/temporal_features/winding-verification.json',
            'downloaded_registered_cbct':[json.loads((OUT/'cbct-download.json').read_text())],
            'outcomes':rows,
            'mastoid_foramen_variant':{'code':'A02.1.06.008','bodyparts3d_records':2,'confirmed_native_geometry':False,
                'finding':'Естественный канал сосцевидного эмиссария не прослежен. Отверстия губчатого вещества и повреждения края не названы сосцевидным отверстием.'}}
    if (OUT/'cbct-full-download.json').exists():
        result['downloaded_registered_cbct'].append(json.loads((OUT/'cbct-full-download.json').read_text()))
    (ROOT/'research/temporal-feature-review.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(f'43 code outcomes, {len(markers)} native wall landmarks; no full-channel claim')


if __name__=='__main__':
    main()
